-- 검증(읽기 전용): ap_precalculus. ok 가 모두 true 여야 한다.
select 'subject' as check, 1 as expected, (select count(*) from subjects where ap_subject_code = 'ap_precalculus') as actual, 1 = (select count(*) from subjects where ap_subject_code = 'ap_precalculus') as ok
union all
select 'edition' as check, 1 as expected, (select count(*) from ap_curriculum_editions where subject_id = (select id from subjects where ap_subject_code = 'ap_precalculus') and edition = 'ced-2027') as actual, 1 = (select count(*) from ap_curriculum_editions where subject_id = (select id from subjects where ap_subject_code = 'ap_precalculus') and edition = 'ced-2027') as ok
union all
select 'skills' as check, 3 as expected, (select count(*) from ap_skills where subject_id = (select id from subjects where ap_subject_code = 'ap_precalculus') and edition = 'ced-2027') as actual, 3 = (select count(*) from ap_skills where subject_id = (select id from subjects where ap_subject_code = 'ap_precalculus') and edition = 'ced-2027') as ok
union all
select 'weights' as check, 3 as expected, (select count(*) from ap_exam_weights where subject_id = (select id from subjects where ap_subject_code = 'ap_precalculus') and edition = 'ced-2027') as actual, 3 = (select count(*) from ap_exam_weights where subject_id = (select id from subjects where ap_subject_code = 'ap_precalculus') and edition = 'ced-2027') as ok
union all
select 'folders(units)' as check, 3 as expected, (select count(*) from subject_keyword_folders where subject_id = (select id from subjects where ap_subject_code = 'ap_precalculus') and official_code in ('1','2','3')) as actual, 3 = (select count(*) from subject_keyword_folders where subject_id = (select id from subjects where ap_subject_code = 'ap_precalculus') and official_code in ('1','2','3')) as ok
union all
select 'keywords L1' as check, 44 as expected, (select count(*) from subject_keywords where subject_id = (select id from subjects where ap_subject_code = 'ap_precalculus') and level = 1 and source = 'ced') as actual, 44 = (select count(*) from subject_keywords where subject_id = (select id from subjects where ap_subject_code = 'ap_precalculus') and level = 1 and source = 'ced') as ok
union all
select 'keywords L2' as check, 88 as expected, (select count(*) from subject_keywords where subject_id = (select id from subjects where ap_subject_code = 'ap_precalculus') and level = 2 and source = 'ced') as actual, 88 = (select count(*) from subject_keywords where subject_id = (select id from subjects where ap_subject_code = 'ap_precalculus') and level = 2 and source = 'ced') as ok
union all
select 'L2 without parent' as check, 0 as expected, (select count(*) from subject_keywords where subject_id = (select id from subjects where ap_subject_code = 'ap_precalculus') and level = 2 and parent_keyword_id is null) as actual, 0 = (select count(*) from subject_keywords where subject_id = (select id from subjects where ap_subject_code = 'ap_precalculus') and level = 2 and parent_keyword_id is null) as ok
union all
select 'keywords without folder' as check, 0 as expected, (select count(*) from subject_keywords where subject_id = (select id from subjects where ap_subject_code = 'ap_precalculus') and source = 'ced' and folder_id is null) as actual, 0 = (select count(*) from subject_keywords where subject_id = (select id from subjects where ap_subject_code = 'ap_precalculus') and source = 'ced' and folder_id is null) as ok
union all
select 'lessons' as check, 21 as expected, (select count(*) from subject_template_units where subject_id = (select id from subjects where ap_subject_code = 'ap_precalculus') and official_code in ('C1.01','C1.02','C1.03','C1.04','C1.05','C1.06','C2.01','C2.02','C2.03','C2.04','C2.05','C2.06','C3.01','C3.02','C3.03','C3.04','C3.05','C3.06','CX.1','CX.2','CX.3')) as actual, 21 = (select count(*) from subject_template_units where subject_id = (select id from subjects where ap_subject_code = 'ap_precalculus') and official_code in ('C1.01','C1.02','C1.03','C1.04','C1.05','C1.06','C2.01','C2.02','C2.03','C2.04','C2.05','C2.06','C3.01','C3.02','C3.03','C3.04','C3.05','C3.06','CX.1','CX.2','CX.3')) as ok
union all
select 'lesson links' as check, 190 as expected, (select count(*) from subject_template_unit_keywords k join subject_template_units t on t.id = k.unit_id where t.subject_id = (select id from subjects where ap_subject_code = 'ap_precalculus') and t.official_code in ('C1.01','C1.02','C1.03','C1.04','C1.05','C1.06','C2.01','C2.02','C2.03','C2.04','C2.05','C2.06','C3.01','C3.02','C3.03','C3.04','C3.05','C3.06','CX.1','CX.2','CX.3')) as actual, 190 = (select count(*) from subject_template_unit_keywords k join subject_template_units t on t.id = k.unit_id where t.subject_id = (select id from subjects where ap_subject_code = 'ap_precalculus') and t.official_code in ('C1.01','C1.02','C1.03','C1.04','C1.05','C1.06','C2.01','C2.02','C2.03','C2.04','C2.05','C2.06','C3.01','C3.02','C3.03','C3.04','C3.05','C3.06','CX.1','CX.2','CX.3')) as ok
union all
select 'primary links' as check, 132 as expected, (select count(*) from subject_template_unit_keywords k join subject_template_units t on t.id = k.unit_id where t.subject_id = (select id from subjects where ap_subject_code = 'ap_precalculus') and k.role = 'primary') as actual, 132 = (select count(*) from subject_template_unit_keywords k join subject_template_units t on t.id = k.unit_id where t.subject_id = (select id from subjects where ap_subject_code = 'ap_precalculus') and k.role = 'primary') as ok;
